#include <iostream>
#include <string>

class CourseRecord {
public:
    // Explicit single-argument constructor with member initializer list
    explicit CourseRecord(std::string courseId)
        : id{std::move(courseId)}, studentCount{0} {
        // Constructor body executes after initializers
    }

    // Explicitly defaulted zero-argument constructor (C++11/C++17)
    CourseRecord() : id{"Unassigned"}, studentCount{0} {}

    void display() const {
        std::cout << "Course: " << id << ", Students: " << studentCount << "\n";
    }

private:
    std::string id;
    int studentCount;
};

int main() {
    CourseRecord c1{"CS101"};
    CourseRecord c2{};
    c1.display();
    c2.display();
    return 0;
}

#include <iostream>
#include <string>

// Emulating header content: strictly using std:: qualification
class GradeBook {
public:
    explicit GradeBook(std::string name)
        : courseName{std::move(name)} {}

    void setCourseName(std::string name) {
        courseName = std::move(name);
    }

    std::string getCourseName() const {
        return courseName;
    }

    void displayMessage() const {
        std::cout << "Welcome to the grade book for\n" << getCourseName() << "!\n";
    }

private:
    std::string courseName; // Object size is determined solely by this data member
};

// Driver program emulation (equivalent to fig03_10.cpp)
int main() {
    GradeBook gradeBook1{"CS101 Introduction to C++ Programming"};
    GradeBook gradeBook2{"CS102 Data Structures in C++"};

    std::cout << "gradeBook1 created for course: " << gradeBook1.getCourseName() << "\n";
    std::cout << "gradeBook2 created for course: " << gradeBook2.getCourseName() << "\n";

    // Verify memory characteristics: size of object matches size of its member
    std::cout << "Object size in bytes: " << sizeof(gradeBook1) << "\n";
    std::cout << "std::string size in bytes: " << sizeof(std::string) << "\n";

    return 0;
}
